<script setup>
import {ref,onUnmounted} from 'vue';import BaseModal from '../components/BaseModal.vue';import {state,api,useResource,changed,notify} from '../lib/workspace';
const show=ref(false),form=ref({}),error=ref(''),busy=ref(false);const {data,error:loadError}=useResource(()=>api('/users'),[]);
function open(u=null){form.value=u?JSON.parse(JSON.stringify(u)):{username:'',password:'',role:'viewer',active:true,company_ids:[]};form.value.password='';error.value='';show.value=true;state.editor={name:'Permissões de usuário'};}
function close(){if(busy.value)return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{await api('/users'+(form.value.id?'/'+form.value.id:''),{method:form.value.id?'PUT':'POST',body:form.value});show.value=false;state.editor=null;changed();notify('Permissões salvas. Sessões anteriores deste usuário foram encerradas.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ADMINISTRAÇÃO</div><h1>Usuários e empresas</h1><p>Administrador acessa todas as empresas. Os demais perfis usam as empresas atribuídas.</p></div><button class="button primary" @click="open()">Novo usuário</button></header><p v-if="loadError" class="message error">{{loadError}}</p><section class="panel"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Situação</th><th>Empresas</th><th></th></tr></thead><tbody><tr v-for="u in data" :key="u.id"><td>{{u.username}}</td><td>{{({admin:'Administrador',operator:'Operador',viewer:'Consulta'})[u.role]}}</td><td>{{u.active?'Ativo':'Desativado'}}</td><td>{{u.role==='admin'?'Todas':u.company_ids.length}}</td><td><button class="button small" @click="open(u)">Editar acesso</button></td></tr></tbody></table></section><BaseModal v-if="show" title="Acesso do usuário" @close="close"><p v-if="error" class="message error">{{error}}</p><form id="user-form" @submit.prevent="save"><div class="form-grid"><label>Usuário<input v-model="form.username" required/></label><label>{{form.id?'Nova senha (opcional)':'Senha'}}<input v-model="form.password" type="password" autocomplete="new-password" minlength="12" :required="!form.id"/></label><label>Perfil<select v-model="form.role"><option value="viewer">Consulta</option><option value="operator">Operador</option><option value="admin">Administrador</option></select></label><label>Situação<select v-model="form.active"><option :value="true">Ativo</option><option :value="false">Desativado</option></select></label></div><fieldset v-if="form.role!=='admin'"><legend>Empresas permitidas</legend><label v-for="c in state.companies" :key="c.id" class="inline-choice"><input v-model="form.company_ids" type="checkbox" :value="c.id"/>{{c.code}} · {{c.name}}</label></fieldset></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="user-form" :disabled="busy">Salvar acesso</button></template></BaseModal></div></template>
